public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType == null || targetType == null) {
        return null;
    }
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType pt = (ParameterizedType) genericType;
    Type[] args = pt.getActualTypeArguments();
    Class<?>[] result = new Class<?>[args.length];
    for (int i = 0; i < args.length; i++) {
        Type t = args[i];
        if (t instanceof Class<?>) {
            result[i] = (Class<?>) t;
        } else if (t instanceof ParameterizedType) {
            Type raw = ((ParameterizedType) t).getRawType();
            if (raw instanceof Class<?>) {
                result[i] = (Class<?>) raw;
            } else {
                return null;
            }
        } else if (t instanceof TypeVariable<?>) {
            // Attempt to resolve type variable using targetType's type parameters
            TypeVariable<?> tv = (TypeVariable<?>) t;
            // Search in targetType's generic superclass
            Type genericSuper = targetType.getGenericSuperclass();
            if (genericSuper instanceof ParameterizedType) {
                ParameterizedType ps = (ParameterizedType) genericSuper;
                TypeVariable<?>[] tvs = ((Class<?>) ps.getRawType()).getTypeParameters();
                Type[] actuals = ps.getActualTypeArguments();
                for (int j = 0; j < tvs.length; j++) {
                    if (tvs[j].getName().equals(tv.getName())) {
                        Type actual = actuals[j];
                        if (actual instanceof Class<?>) {
                            result[i] = (Class<?>) actual;
                            break;
                        }
                    }
                }
            }
            if (result[i] == null) {
                return null;
            }
        } else {
            return null;
        }
    }
    return result;
}

@Override public void accept(final METRICS data) {
    if (data == null) {
        return;
    }
    try {
        // Ensure the cache map exists
        if (cache == null) {
            cache = new java.util.HashMap<>();
        }
        // Assume METRICS has a method to obtain a unique key
        String key = data.getKey();
        if (key == null) {
            return;
        }
        METRICS existing = cache.get(key);
        if (existing != null) {
            // Try to merge the new data into the existing entry
            try {
                existing.merge(data);
            } catch (NoSuchMethodError | UnsupportedOperationException e) {
                // If merge is not supported, replace the entry
                cache.put(key, data);
            }
        } else {
            cache.put(key, data);
        }
    } catch (RuntimeException e) {
        // Log the error without throwing to keep the method non‑thread‑safe
        System.err.println("Failed to accept metrics: " + e.getMessage());
    }
}

void insertBefore(Bucket bucket) {
    if (bucket == null) {
        throw new IllegalArgumentException("bucket cannot be null");
    }
    if (bucket == this) {
        throw new IllegalArgumentException("cannot insert before itself");
    }

    // Detach this bucket from its current position if necessary
    if (this.prev != null) {
        this.prev.next = this.next;
    }
    if (this.next != null) {
        this.next.prev = this.prev;
    }

    // Insert this bucket before the specified bucket
    this.next = bucket;
    this.prev = bucket.prev;

    if (bucket.prev != null) {
        bucket.prev.next = this;
    }
    bucket.prev = this;
}

public Mappings diffStructure(String tableName, Mappings mappings) {
    try {
        if (tableName == null || mappings == null) {
            return new Mappings();
        }
        // Retrieve the current mapping for the given table name.
        Mappings current = fetchCurrentMappings(tableName);
        if (current == null) {
            return new Mappings();
        }
        Map<String, Object> currentProps = current.getProperties();
        Map<String, Object> inputProps = mappings.getProperties();
        if (currentProps == null) {
            return new Mappings();
        }
        if (inputProps == null) {
            inputProps = Collections.emptyMap();
        }
        Mappings diff = new Mappings();
        for (Map.Entry<String, Object> entry : currentProps.entrySet()) {
            String field = entry.getKey();
            // Skip the _source configuration to avoid update conflicts.
            if ("_source".equals(field)) {
                continue;
            }
            if (!inputProps.containsKey(field)) {
                diff.put(field, entry.getValue());
            }
        }
        return diff;
    } catch (Exception e) {
        // In case of any unexpected error, return an empty mapping.
        return new Mappings();
    }
}

