static long compressTimeBucket(long timeBucket,int dayStep){
    if(dayStep <= 0){
        return timeBucket;
    }
    try{
        int year  = (int)(timeBucket / 10000);
        int month = (int)((timeBucket % 10000) / 100);
        int day   = (int)(timeBucket % 100);
        int newDay = ((day - 1) / dayStep) * dayStep + 1;
        // Ensure newDay does not exceed the maximum days in the month
        // (optional, but safe for months with fewer days)
        int maxDay = java.time.YearMonth.of(year, month).lengthOfMonth();
        if(newDay > maxDay){
            newDay = maxDay;
        }
        return year * 10000L + month * 100L + newDay;
    }catch(Exception e){
        return timeBucket;
    }
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new NullPointerException("str");
    }
    int strLen = str.length();
    if (index < 0 || index > strLen) {
        throw new IndexOutOfBoundsException("index out of bounds");
    }
    if (len < 0 || index + len > strLen) {
        throw new IndexOutOfBoundsException("len out of bounds");
    }
    int size = 0;
    int end = index + len;
    for (int i = index; i < end; i++) {
        char ch = str.charAt(i);
        if (Character.isHighSurrogate(ch)) {
            if (i + 1 < end && Character.isLowSurrogate(str.charAt(i + 1))) {
                int codePoint = Character.toCodePoint(ch, str.charAt(i + 1));
                if (codePoint <= 0x7F) {
                    size += 1;
                } else if (codePoint <= 0x7FF) {
                    size += 2;
                } else if (codePoint <= 0xFFFF) {
                    size += 3;
                } else {
                    size += 4;
                }
                i++; // skip low surrogate
            } else {
                // lone high surrogate, encode as replacement character
                size += 3;
            }
        } else if (Character.isLowSurrogate(ch)) {
            // lone low surrogate, encode as replacement character
            size += 3;
        } else {
            int cp = ch;
            if (cp <= 0x7F) {
                size += 1;
            } else if (cp <= 0x7FF) {
                size += 2;
            } else if (cp <= 0xFFFF) {
                size += 3;
            } else {
                size += 4;
            }
        }
    }
    return size;
}

