public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> result = new java.util.ArrayList<>();
    if (u == null) {
        return result;
    }
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return result;
    }
    // Ignore leading '/' if present
    if (path.startsWith("/")) {
        path = path.substring(1);
    }
    String[] segments = path.split("/");
    for (String seg : segments) {
        if (seg.isEmpty()) {
            continue;
        }
        String decoded = seg;
        if (decode) {
            try {
                decoded = java.net.URLDecoder.decode(seg, "UTF-8");
            } catch (java.io.UnsupportedEncodingException e) {
                // Fallback to original segment if decoding fails
                decoded = seg;
            }
        }
        // Attempt to instantiate PathSegmentImpl using available constructors
        PathSegmentImpl segmentObj = null;
        try {
            java.lang.reflect.Constructor<?> ctor = PathSegmentImpl.class.getConstructor(String.class, String.class);
            segmentObj = (PathSegmentImpl) ctor.newInstance(seg, decoded);
        } catch (Exception e1) {
            try {
                java.lang.reflect.Constructor<?> ctor = PathSegmentImpl.class.getConstructor(String.class);
                segmentObj = (PathSegmentImpl) ctor.newInstance(seg);
            } catch (Exception e2) {
                // If no suitable constructor, skip this segment
                continue;
            }
        }
        if (segmentObj != null) {
            result.add(segmentObj);
        }
    }
    return result;
}

