                if (Modifier.isStatic(mods) || Modifier.isTransient(mods)) {
                    continue;
                }
                field.setAccessible(true);
                Object value = field.get(this);
                writer.key(field.getName()).value(value);
            }
            clazz = clazz.getSuperclass();
        }
        writer.endObject();
        return sw.toString();
    } catch (Exception e) {
        throw new RuntimeException(e);
    }
}

