public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 2) {
        return 2;
    }
    int candidate = desiredCapacity;
    // Ensure candidate is odd (except for 2)
    if (candidate % 2 == 0) {
        candidate++;
    }
    while (true) {
        boolean isPrime = true;
        if (candidate < 2) {
            isPrime = false;
        } else {
            int sqrt = (int) Math.sqrt(candidate);
            for (int i = 2; i <= sqrt; i++) {
                if (candidate % i == 0) {
                    isPrime = false;
                    break;
                }
            }
        }
        if (isPrime) {
            return candidate;
        }
        // Move to next odd number
        if (candidate > Integer.MAX_VALUE - 2) {
            // In case of overflow, return Integer.MAX_VALUE
            return Integer.MAX_VALUE;
        }
        candidate += 2;
    }
}

