public final byte[] toByteArray(){
    try {
        java.util.List<java.nio.ByteBuffer> buffers = new java.util.ArrayList<>();
        java.util.List<java.io.ByteArrayOutputStream> streams = new java.util.ArrayList<>();
        java.lang.reflect.Field[] fields = this.getClass().getDeclaredFields();
        for (java.lang.reflect.Field f : fields) {
            f.setAccessible(true);
            if (java.nio.ByteBuffer.class.isAssignableFrom(f.getType())) {
                java.nio.ByteBuffer buf = (java.nio.ByteBuffer) f.get(this);
                if (buf != null) {
                    buffers.add(buf);
                }
            } else if (java.io.ByteArrayOutputStream.class.isAssignableFrom(f.getType())) {
                java.io.ByteArrayOutputStream stream = (java.io.ByteArrayOutputStream) f.get(this);
                if (stream != null) {
                    streams.add(stream);
                }
            }
        }
        int totalSize = 0;
        for (java.nio.ByteBuffer buf : buffers) {
            totalSize += buf.remaining();
        }
        for (java.io.ByteArrayOutputStream stream : streams) {
            totalSize += stream.size();
        }
        byte[] result = new byte[totalSize];
        int pos = 0;
        for (java.nio.ByteBuffer buf : buffers) {
            java.nio.ByteBuffer dup = buf.duplicate();
            int len = dup.remaining();
            dup.get(result, pos, len);
            pos += len;
        }
        for (java.io.ByteArrayOutputStream stream : streams) {
            byte[] data = stream.toByteArray();
            System.arraycopy(data, 0, result, pos, data.length);
            pos += data.length;
        }
        return result;
    } catch (Exception e) {
        return new byte[0];
    }
}

public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(str.length());
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i + 1 >= str.length()) {
                throw new Exception("Trailing backslash");
            }
            char next = str.charAt(++i);
            switch (next) {
                case 'b':
                    sb.append('\b');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case 'n':
                    sb.append('\n');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case '\"':
                    sb.append('\"');
                    break;
                case '\'':
                    sb.append('\'');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                case 'u':
                    if (i + 4 >= str.length()) {
                        throw new Exception("Invalid unicode escape");
                    }
                    String hex = str.substring(i + 1, i + 5);
                    try {
                        int code = Integer.parseInt(hex, 16);
                        sb.append((char) code);
                    } catch (NumberFormatException e) {
                        throw new Exception("Invalid unicode escape: \\u" + hex);
                    }
                    i += 4;
                    break;
                default:
                    if (next >= '0' && next <= '7') {
                        int j = i;
                        int val = next - '0';
                        int count = 1;
                        while (count < 3 && j + 1 < str.length()
                                && str.charAt(j + 1) >= '0' && str.charAt(j + 1) <= '7') {
                            val = val * 8 + (str.charAt(++j) - '0');
                            count++;
                        }
                        sb.append((char) val);
                        i = j;
                    } else {
                        throw new Exception("Unknown escape sequence: \\" + next);
                    }
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

