        return (char)(c - 'A' + 10);
    }
    return Character.MAX_VALUE;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate,Node start,Node stop,int dir){
    if (predicate == null) {
        throw new IllegalArgumentException("predicate must not be null");
    }
    if (start == null || stop == null) {
        return null;
    }
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
    // If start is the stop node, return immediately
    if (circ.getNode().equals(stop)) {
        return circ;
    }
    while (circ != null && !circ.getNode().equals(stop)) {
        if (predicate.test(circ.getNode())) {
            return circ;
        }
        circ = circ.next();
    }
    // If we exit the loop, circ is either null or at the stop node
    return circ;
}

