        return this;
    }
    // Ensure capacity
    int newSize = size + byteLength;
    if(buffer == null || newSize > buffer.length){
        int newCapacity = Math.max(buffer == null ? byteLength : buffer.length * 2, newSize);
        byte[] newBuffer = new byte[newCapacity];
        if(buffer != null){
            System.arraycopy(buffer, 0, newBuffer, 0, size);
        }
        buffer = newBuffer;
    }
    if(byteArrayValue == null){
        // Fill with nullbytes (zeros)
        for(int i = 0; i < byteLength; i++){
            buffer[size + i] = 0;
        }
    } else {
        if(byteOffset < 0 || byteLength < 0 || byteOffset + byteLength > byteArrayValue.length){
            throw new IndexOutOfBoundsException("byteOffset and byteLength out of bounds");
