protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("tour and graph must not be null");
    }
    if (tour.isEmpty()) {
        return new GraphWalk<>(graph, null, null, 0.0, new ArrayList<>(), new ArrayList<>());
    }
    Map<V, List<E>> adjacency = new HashMap<>();
    for (E e : tour) {
        V source = graph.getEdgeSource(e);
        V target = graph.getEdgeTarget(e);
        adjacency.computeIfAbsent(source, k -> new ArrayList<>()).add(e);
        adjacency.computeIfAbsent(target, k -> new ArrayList<>()).add(e);
    }
    V start = null;
    for (Map.Entry<V, List<E>> entry : adjacency.entrySet()) {
        if (entry.getValue().size() == 1) {
            start = entry.getKey();
            break;
        }
    }
    if (start == null) {
        start = adjacency.keySet().iterator().next();
    }
    List<V> vertices = new ArrayList<>();
    List<E> edges = new ArrayList<>();
    Set<E> visited = new HashSet<>();
    V current = start;
    while (true) {
        vertices.add(current);
        List<E> adjEdges = adjacency.get(current);
        if (adjEdges == null) break;
        E nextEdge = null;
        for (E e : adjEdges) {
            if (!visited.contains(e)) {
                nextEdge = e;
                break;
            }
        }
        if (nextEdge == null) {
            break;
        }
        edges.add(nextEdge);
        visited.add(nextEdge);
        V next = graph.getEdgeSource(nextEdge).equals(current) ? graph.getEdgeTarget(nextEdge) : graph.getEdgeSource(nextEdge);
        current = next;
    }
    vertices.add(current);
    double weight = 0.0;
    for (E e : edges) {
        weight += graph.getEdgeWeight(e);
    }
    return new GraphWalk<>(graph, vertices.get(0), vertices.get(vertices.size() - 1), weight, vertices, edges);
}

