private String unescapeId(String input){
    if (input == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        if (c == '\\' && i + 1 < input.length()) {
            char next = input.charAt(i + 1);
            switch (next) {
                case 'n':
                    sb.append('\n');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case 'b':
                    sb.append('\b');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                case '\"':
                    sb.append('\"');
                    break;
                case '\'':
                    sb.append('\'');
                    break;
                default:
                    sb.append(next);
                    break;
            }
            i++; // skip the escaped character
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

