void removeSelf() {
    try {
        // Adjust neighboring links if this bucket is part of a doubly linked list
        if (prev != null) {
            prev.next = next;
        }
        if (next != null) {
            next.prev = prev;
        }

        // If this bucket is the head of a list, update the head reference in the parent container
        if (parent != null) {
            if (parent.head == this) {
                parent.head = next;
            }
            // Attempt to notify the parent container that this bucket is removed
            try {
                parent.removeBucket(this);
            } catch (NoSuchMethodError | UnsupportedOperationException ignored) {
                // Parent does not expose a removeBucket method; ignore
            }
        }

        // Clear references to aid garbage collection
        prev = null;
        next = null;
        parent = null;
    } catch (Exception e) {
        throw new RuntimeException("Failed to remove bucket", e);
    }
}

