private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    if (bounds == null || bounds.isEmpty()){
        return new Pair<>(new ArrayList<>(), 0L);
    }
    int n = bounds.size();
    List<Integer> suffix = new ArrayList<>(n);
    for (int i = 0; i < n; i++) {
        suffix.add(0);
    }
    long runningSum = 0L;
    for (int i = n - 1; i >= 0; i--) {
        Integer val = bounds.get(i);
        if (val == null) {
            throw new IllegalArgumentException("bounds list contains null at index " + i);
        }
        runningSum += val;
        suffix.set(i, (int) runningSum);
    }
    return new Pair<>(suffix, runningSum);
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        throw new NullPointerException("Array must not be null");
    }
    if (from < 0 || to >= arr.length) {
        throw new IllegalArgumentException("Index out of bounds: from=" + from + ", to=" + to + ", length=" + arr.length);
    }
    if (from > to) {
        throw new IllegalArgumentException("from index must be <= to index: from=" + from + ", to=" + to);
    }
    int i = from;
    int j = to;
    while (i < j) {
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
        i++;
        j--;
    }
}

