public ByteVector putInt(final int intValue){
    // Ensure the internal byte array has enough capacity for 4 more bytes
    if (data == null) {
        data = new byte[4];
        size = 0;
    }
    int newSize = size + 4;
    if (data.length < newSize) {
        int newCapacity = Math.max(data.length * 2, newSize);
        byte[] newData = new byte[newCapacity];
        System.arraycopy(data, 0, newData, 0, size);
        data = newData;
    }
    // Write the int in big-endian order
    data[size]     = (byte)(intValue >>> 24);
    data[size + 1] = (byte)(intValue >>> 16);
    data[size + 2] = (byte)(intValue >>> 8);
    data[size + 3] = (byte)intValue;
    size = newSize;
    return this;
}

public static boolean arrayequals(byte[] a, byte[] b, int count) {
    // If both references are the same, they are equal
    if (a == b) {
        return true;
    }
    // If either array is null, they cannot be equal
    if (a == null || b == null) {
        return false;
    }
    // Non‑positive count means nothing to compare – treat as equal
    if (count <= 0) {
        return true;
    }
    // If count exceeds the length of either array, the comparison cannot be performed
    if (count > a.length || count > b.length) {
        return false;
    }
    // Compare byte by byte
    for (int i = 0; i < count; i++) {
        if (a[i] != b[i]) {
            return false;
        }
    }
    return true;
}

public void abbreviate(final int nameStart, final StringBuffer buf) {
    // Assume the class has a field `name` containing the full name to abbreviate.
    if (name == null) {
        return;
    }
    int len = name.length();
    int start = nameStart;
    if (start < 0) {
        start = 0;
    }
    if (start >= len) {
        return;
    }
    String sub = name.substring(start);
    // Split the name by '.' to get package/class components.
    String[] parts = sub.split("\\.");
    for (int i = 0; i < parts.length; i++) {
        String part = parts[i];
        if (part.isEmpty()) {
            continue;
        }
        // For all but the last component, append the first character followed by a dot.
        if (i < parts.length - 1) {
            buf.append(part.charAt(0)).append('.');
        } else {
            // Append the full last component (usually the class name).
            buf.append(part);
        }
    }
}

public static Type resolveBound(TypeVariable<?> typeVariable) {
    try {
        if (typeVariable == null) {
            return Unknown.class;
        }
        Type[] bounds = typeVariable.getBounds();
        if (bounds == null || bounds.length == 0) {
            return Unknown.class;
        }
        Type first = bounds[0];
        if (first instanceof Class<?>) {
            return first;
        }
        if (first instanceof ParameterizedType) {
            Type raw = ((ParameterizedType) first).getRawType();
            if (raw instanceof Class<?>) {
                return raw;
            }
        }
        // If the bound is not a Class or ParameterizedType, return Unknown
        return Unknown.class;
    } catch (Exception e) {
        // Any unexpected exception results in Unknown
        return Unknown.class;
    }
}

private static <V,E>boolean isClique(Graph<V,E> graph,Set<V> vertices){
    if (graph == null || vertices == null) {
        return false;
    }
    int size = vertices.size();
    if (size <= 1) {
        return true;
    }
    // Convert to array for indexed access
    Object[] verts = vertices.toArray();
    for (int i = 0; i < size; i++) {
        V vi = (V) verts[i];
        for (int j = i + 1; j < size; j++) {
            V vj = (V) verts[j];
            boolean edgeExists;
            try {
                // Prefer containsEdge if available
                edgeExists = graph.containsEdge(vi, vj);
            } catch (UnsupportedOperationException e) {
                // Fallback to getEdge
                edgeExists = graph.getEdge(vi, vj) != null;
            }
            if (!edgeExists) {
                return false;
            }
        }
    }
    return true;
}

private List<Integer> computeLowerBounds(List<K> keys){
    java.util.List<Integer> result = new java.util.ArrayList<>();
    if (keys == null) {
        return result;
    }
    for (K key : keys) {
        if (key == null) {
            result.add(null);
            continue;
        }
        Integer maxLower = null;
        for (K other : keys) {
            if (other == null) continue;
            if (other instanceof Comparable && key instanceof Comparable) {
                @SuppressWarnings("unchecked")
                java.lang.Comparable<Object> comp = (java.lang.Comparable<Object>) other;
                if (comp.compareTo(key) <= 0) {
                    try {
                        Integer val = (Integer) other;
                        if (maxLower == null || val > maxLower) {
                            maxLower = val;
                        }
                    } catch (ClassCastException e) {
                        // skip non-integer values
                    }
                }
            }
        }
        result.add(maxLower);
    }
    return result;
}

