private String buildContentRange(){
    // Build the 'Content-Range' HTTP Header value.
    // Expected format: "bytes start-end/total"
    // If total is unknown, use "*".
    long start = 0;
    long end = -1;
    long total = -1;
    try {
        java.lang.reflect.Field fStart = this.getClass().getDeclaredField("start");
        fStart.setAccessible(true);
        start = fStart.getLong(this);
    } catch (Exception ignored) {}
    try {
        java.lang.reflect.Field fEnd = this.getClass().getDeclaredField("end");
        fEnd.setAccessible(true);
        end = fEnd.getLong(this);
    } catch (Exception ignored) {}
    try {
        java.lang.reflect.Field fTotal = this.getClass().getDeclaredField("total");
        fTotal.setAccessible(true);
        total = fTotal.getLong(this);
    } catch (Exception ignored) {}
    if (end < start) {
        return null;
    }
    String totalStr = (total >= 0) ? Long.toString(total) : "*";
    return "bytes " + start + "-" + end + "/" + totalStr;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file,List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> result = new ArrayList<>();
    if (file == null || !file.isFile()) {
        return result;
    }
    if (timeRanges == null || timeRanges.isEmpty()) {
        return result;
    }
    try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(file))) {
        while (true) {
            Object obj = ois.readObject();
            if (obj instanceof ThreadSnapshot) {
                ThreadSnapshot ts = (ThreadSnapshot) obj;
                long tsTime = ts.getTimestamp();
                for (ProfileAnalyzeTimeRange range : timeRanges) {
                    if (tsTime >= range.getStart() && tsTime <= range.getEnd()) {
                        result.add(ts);
                        break;
                    }
                }
            }
        }
    } catch (EOFException e) {
        // reached end of file
    } catch (ClassNotFoundException e) {
        throw new IOException("Failed to deserialize ThreadSnapshot", e);
    }
    return result;
}
